-- Melhorias editoriais para AdSense, 23/10/2026
-- Requer banco de dados e tabela posts da instalação existente.
-- Idempotente: usa UPDATE por slug, nunca apaga posts nem altera suas URLs.
-- ATENÇÃO: publique primeiro a pasta /imagens/exemplos-carrossel/ e a página /exemplos-de-corte.html
-- Faça backup do banco antes de executar.
SET NAMES utf8mb4;

-- Backup adicional somente das quatro linhas afetadas; a tabela não é sobrescrita.
CREATE TABLE IF NOT EXISTS adsense_posts_backup_20261023 AS
 SELECT * FROM posts WHERE slug IN ('como-dividir-imagem-para-instagram-em-partes-iguais', 'carrossel-splitter-como-dividir-uma-arte-em-slides-automaticamente', 'como-dividir-uma-imagem-em-partes-iguais-online', 'como-fatiar-uma-imagem-para-instagram-sem-perder-qualidade');

START TRANSACTION;

-- como-dividir-imagem-para-instagram-em-partes-iguais
UPDATE posts SET content='<p>Você terminou um desenho panorâmico e quer transformá-lo em slides sem perder a continuidade. O primeiro teste é simples: confira se a largura do arquivo é múltipla do número de slides. Se não for, o programa precisará descartar ou redistribuir alguns pixels.</p>
<h2>Teste com um arquivo de verdade</h2>
<p>Preparei uma arte original com <strong>5400 × 1350 pixels</strong> para cinco páginas em 4:5. Cada corte tem exatamente <strong>1080 × 1350</strong>. A linha laranja atravessa os cinco slides, mas os títulos ficam dentro de cada página.</p>
<figure><img loading="lazy" src="/imagens/exemplos-carrossel/carrossel-continuo-original-5400x1350.png" alt="Arquivo panorâmico original com cinco páginas contínuas de 1080 × 1350 pixels" width="1080"><figcaption>Arquivo panorâmico original com cinco páginas contínuas de 1080 × 1350 pixels</figcaption></figure>
<p><a href="/imagens/exemplos-carrossel/carrossel-continuo-original-5400x1350.png">Baixar a imagem panorâmica original</a> ou <a href="/imagens/exemplos-carrossel/exemplos-carrossel-5-slides.zip">baixar o ZIP com a imagem e os cinco recortes</a> para comparar com o resultado que você gerar.</p>
<h2>Como fazer o corte no site</h2><ol><li>Baixe a imagem panorâmica de teste no link acima.</li><li>Abra a <a href="/">ferramenta principal de corte</a>.</li><li>Selecione o arquivo original, não os slides já divididos.</li><li>Defina <strong>1 linha e 5 colunas</strong>.</li><li>Gere as partes e confira a sequência da esquerda para a direita.</li><li>Compare o resultado com os cinco arquivos do ZIP.</li></ol>
<h2>Como saber se o tamanho está certo</h2><table><thead><tr><th>Slides</th><th>Arquivo completo em 4:5</th><th>Cada parte</th></tr></thead><tbody><tr><td>3</td><td>3240 × 1350</td><td>1080 × 1350</td></tr><tr><td>5</td><td>5400 × 1350</td><td>1080 × 1350</td></tr><tr><td>7</td><td>7560 × 1350</td><td>1080 × 1350</td></tr></tbody></table>
<p>Se estiver preparando um arquivo do zero, use a <a href="/calculadora-carrossel.html">calculadora de carrossel</a> para obter a largura e as posições das guias antes de começar o layout.</p>
<h2>O que deve continuar de um slide para o outro?</h2><p>Fundos, linhas, fotos e formas podem atravessar as divisões. Evite repartir palavras e informações importantes, porque o usuário pode ver apenas um slide por vez. No exemplo acima, repare que a linha atravessa todas as páginas enquanto os textos permanecem legíveis individualmente.</p>
<h2>Quando o resultado não encaixa</h2><ul><li><strong>Degrau entre linhas:</strong> confirme que os arquivos estão na ordem correta e não foram redimensionados separadamente.</li><li><strong>Slide estreito demais:</strong> confira a largura do arquivo original e a quantidade de colunas.</li><li><strong>Texto cortado ao meio:</strong> volte ao design e afaste as palavras da guia de 1080 pixels.</li><li><strong>Imagem embaçada:</strong> use o arquivo exportado do editor, não um print do celular.</li></ul>
<p>Você pode ver a arte antes e depois do corte na <a href="/exemplos-de-corte.html">página de exemplos para baixar</a> ou ler o guia específico de <a href="/guias/como-cortar-carrossel-no-canva/">montagem no Canva</a>.</p>' WHERE slug='como-dividir-imagem-para-instagram-em-partes-iguais';

-- carrossel-splitter-como-dividir-uma-arte-em-slides-automaticamente
UPDATE posts SET content='<p>O carrossel splitter resolve uma tarefa específica: receber uma arte longa e separar suas páginas com cortes iguais. O problema aparece quando o arquivo recebido não foi preparado para a quantidade de slides desejada. Este guia mostra como verificar isso antes de apertar o botão.</p>
<h2>Teste reproduzível: cinco slides</h2><p>O nosso arquivo de exemplo mede 5400 × 1350 px. Ao selecionar 1 linha e 5 colunas, o splitter divide 5400 por 5. O resultado é uma largura de 1080 px para cada slide, mantendo a altura de 1350 px.</p>
<figure><img loading="lazy" src="/imagens/exemplos-carrossel/carrossel-continuo-original-5400x1350.png" alt="Imagem panorâmica de teste criada para ser dividida em cinco slides perfeitamente iguais" width="1080"><figcaption>Imagem panorâmica de teste criada para ser dividida em cinco slides perfeitamente iguais</figcaption></figure>
<p><a href="/imagens/exemplos-carrossel/carrossel-continuo-original-5400x1350.png">Baixe o arquivo e faça seu próprio corte</a>. Se quiser um gabarito para conferir, <a href="/imagens/exemplos-carrossel/exemplos-carrossel-5-slides.zip">baixe os cinco slides prontos no ZIP</a>.</p>
<h2>O que acontece quando a conta não fecha?</h2><p>Imagine um arquivo com 5403 px de largura, dividido em cinco colunas. O cálculo daria 1080,6 px por coluna, mas um PNG não pode ter largura fracionária. Algumas ferramentas recortam pixels das bordas, outras redistribuem as sobras. Por isso, sempre confirme a dimensão do resultado.</p>
<table><thead><tr><th>Arquivo</th><th>Divisão</th><th>Conferência</th></tr></thead><tbody><tr><td>5400 × 1350</td><td>5 colunas</td><td>1080 × 1350 exatos</td></tr><tr><td>3240 × 1350</td><td>3 colunas</td><td>1080 × 1350 exatos</td></tr><tr><td>5403 × 1350</td><td>5 colunas</td><td>Há 3 pixels excedentes que exigem tratamento</td></tr></tbody></table>
<h2>Etapa a etapa</h2><ol><li>Identifique o número de slides previsto na arte.</li><li>Confira a dimensão do arquivo mestre.</li><li>Abra <a href="/dividir-imagem.html">o divisor de imagens</a> e escolha 1 linha.</li><li>Preencha a quantidade de colunas equivalente aos slides.</li><li>Leia eventuais avisos sobre bordas e pixels excedentes antes do download.</li><li>Depois de baixar, abra os arquivos na sequência e verifique as bordas.</li></ol>
<h2>Splitter, calculadora ou editor?</h2><p>A <a href="/calculadora-carrossel.html">calculadora</a> define o tamanho antes do design. O editor (Canva, Figma ou outro) monta a imagem. O splitter separa a arte já pronta. Se uma legenda ficou sobre a divisão, o splitter não consegue reposicioná-la: essa correção deve ser feita no editor.</p>
<h2>Para além do Instagram</h2><p>Se você quer uma grade 2 × 2 para mosaico, não use a configuração de carrossel horizontal. Selecione duas linhas e duas colunas. Na <a href="/exemplos-de-corte.html">página de exemplos</a> há um segundo arquivo original, de 2160 × 2160 px, com os quatro recortes correspondentes.</p>' WHERE slug='carrossel-splitter-como-dividir-uma-arte-em-slides-automaticamente';

-- como-dividir-uma-imagem-em-partes-iguais-online
UPDATE posts SET content='<p>Nem toda divisão de imagens serve para carrossel. Para mosaicos, quadrantes, jogos visuais e páginas de impressão, você pode precisar de linhas <em>e</em> colunas. Uma grade 2 × 2, por exemplo, exige quatro arquivos dispostos em duas fileiras.</p>
<h2>Exemplo original: imagem de 2160 × 2160 pixels</h2><p>Criei a imagem abaixo com uma linha diagonal atravessando os quadrantes. Para obter partes iguais, basta dividir em 2 linhas e 2 colunas. Cada arquivo resultante deve medir 1080 × 1080 px.</p>
<figure><img loading="lazy" src="/imagens/exemplos-carrossel/mosaico-original-2160x2160.png" alt="Imagem quadrada de 2160 × 2160 para dividir em quatro quadrantes de 1080 × 1080" width="1080"><figcaption>Imagem quadrada de 2160 × 2160 para dividir em quatro quadrantes de 1080 × 1080</figcaption></figure>
<p><a href="/imagens/exemplos-carrossel/mosaico-original-2160x2160.png">Baixar a imagem original</a> e <a href="/imagens/exemplos-carrossel/exemplos-mosaico-2x2.zip">baixar o ZIP com os quatro quadrantes</a>.</p>
<h2>Faça o teste</h2><ol><li>Abra o <a href="/dividir-imagem.html">divisor de imagens em partes iguais</a>.</li><li>Selecione a imagem original de 2160 × 2160 px.</li><li>Indique <strong>2 linhas e 2 colunas</strong>.</li><li>Gere os recortes e confira se cada um ficou com 1080 × 1080 px.</li><li>Monte as quatro partes na ordem: superior esquerda, superior direita, inferior esquerda, inferior direita.</li></ol>
<h2>Divisão horizontal, vertical e em grade</h2><table><thead><tr><th>Objetivo</th><th>Linhas</th><th>Colunas</th></tr></thead><tbody><tr><td>Carrossel de 5 slides</td><td>1</td><td>5</td></tr><tr><td>Três faixas horizontais</td><td>3</td><td>1</td></tr><tr><td>Mosaico de 4 quadrantes</td><td>2</td><td>2</td></tr><tr><td>Mosaico de 9 quadrados</td><td>3</td><td>3</td></tr></tbody></table>
<h2>O que fazer com pixels excedentes?</h2><p>Para gerar quatro quadrados idênticos, as dimensões da imagem precisam ser divisíveis por dois. Se o arquivo medir 2161 × 2160 px, sobrará um pixel na largura. O divisor do site trabalha com a maior área central que permite partes iguais; por isso pode remover pixels das extremidades. Se a borda for importante, ajuste o arquivo original antes de cortar.</p>
<h2>Não confunda mosaico com carrossel</h2><p>No mosaico, o objetivo é recompor uma imagem usando uma grade. No carrossel, geralmente se trata de uma única linha que o usuário percorre deslizando. Para esse segundo caso, veja nosso <a href="/guias/como-dividir-imagem-para-instagram-em-partes-iguais/">teste com cinco slides reais</a>.</p>' WHERE slug='como-dividir-uma-imagem-em-partes-iguais-online';

-- como-fatiar-uma-imagem-para-instagram-sem-perder-qualidade
UPDATE posts SET content='<p>Fatiar uma arte não deveria reduzir a nitidez do desenho. A perda costuma acontecer antes ou depois do corte, por exemplo quando alguém envia um print, amplia uma imagem pequena ou salva o mesmo JPEG várias vezes. Dá para perceber o problema com um teste simples.</p>
<h2>Compare o mesmo desenho em duas versões</h2><p>O primeiro arquivo abaixo foi desenhado diretamente em 1080 × 680 pixels e salvo em PNG. O segundo foi reduzido para 360 px de largura, ampliado de volta e salvo em JPEG com compressão forte, justamente para deixar visíveis as diferenças. <strong>Esse é um exemplo didático de degradação, não uma medição de perda feita pelo Instagram.</strong></p>
<figure><img loading="lazy" src="/imagens/exemplos-carrossel/qualidade-original-png.png" alt="Exemplo de imagem original PNG com letras e linhas nítidas" width="1080"><figcaption>Exemplo de imagem original PNG com letras e linhas nítidas</figcaption></figure>
<figure><img loading="lazy" src="/imagens/exemplos-carrossel/qualidade-recomprimida-exemplo.jpg" alt="Versão didática do mesmo desenho ampliada e recomprimida em JPEG para comparação visual" width="1080"><figcaption>Versão didática do mesmo desenho ampliada e recomprimida em JPEG para comparação visual</figcaption></figure>
<p>Compare os arquivos em tamanho real: <a href="/imagens/exemplos-carrossel/qualidade-original-png.png">PNG original</a> e <a href="/imagens/exemplos-carrossel/qualidade-recomprimida-exemplo.jpg">JPEG degradado de propósito</a>.</p>
<h2>Fluxo que preserva o arquivo</h2><ol><li>Crie o documento já na medida final. Para cinco slides verticais, use 5400 × 1350 px.</li><li>Insira fotos que tenham resolução suficiente para o espaço ocupado.</li><li>Trabalhe no arquivo do editor e evite ficar salvando versões em JPEG sobre JPEG.</li><li>Exporte a arte inteira uma única vez, em PNG quando houver muito texto fino.</li><li>Faça o corte em <a href="/">1 linha e 5 colunas na ferramenta principal</a>.</li><li>Confira a dimensão dos arquivos gerados antes de publicar.</li></ol>
<h2>PNG ou JPEG: qual escolher?</h2><p>Para infográficos, tabelas e tipografia fina, PNG costuma conservar bordas duras. Para fotografias, JPEG em boa qualidade pode reduzir bastante o tamanho do arquivo. O formato não inventa detalhes: uma foto pequena continua pequena mesmo que seja convertida para PNG.</p>
<h2>Teste completo de cinco slides</h2><p>Para conferir se o problema está no recorte ou no arquivo de origem, use nosso <a href="/imagens/exemplos-carrossel/carrossel-continuo-original-5400x1350.png">panorama de teste com 5400 × 1350 px</a> e compare a saída com o <a href="/imagens/exemplos-carrossel/exemplos-carrossel-5-slides.zip">ZIP de cinco slides originais</a>. Uma arte criada com dimensões exatas ajuda a separar defeitos do arquivo de problemas da publicação.</p>
<h2>Um último cuidado</h2><p>O Instagram pode recomprimir os arquivos após o envio. Nenhuma ferramenta de corte controla a compressão final da plataforma. O que você pode controlar é a qualidade do material entregue a ela: dimensão, fontes, contraste, arquivo mestre e quantidade de exportações.</p>
<p>Se o seu desafio for entender onde cada slide começa, leia <a href="/guias/tamanho-carrossel-instagram-2026-medidas-proporcoes-como-cortar/">medidas e cálculo por slide</a>.</p>' WHERE slug='como-fatiar-uma-imagem-para-instagram-sem-perder-qualidade';

COMMIT;

-- Conferência: devem retornar as quatro linhas revisadas.
SELECT id, title, slug, CHAR_LENGTH(content) AS tamanho_html FROM posts WHERE slug IN ('como-dividir-imagem-para-instagram-em-partes-iguais', 'carrossel-splitter-como-dividir-uma-arte-em-slides-automaticamente', 'como-dividir-uma-imagem-em-partes-iguais-online', 'como-fatiar-uma-imagem-para-instagram-sem-perder-qualidade');